// Trouver les créneaux disponibles dans les 5 prochains jours ouvrés
const events = $input.all().map(i => i.json);

// Config
const START_HOUR = 9;
const END_HOUR = 18;
const SLOT_DURATION = 30; // minutes
const DAYS_AHEAD = 5;
const TZ = 'Europe/Paris';

const slots = [];
const now = new Date();

for (let d = 1; d <= DAYS_AHEAD; d++) {
  const date = new Date(now);
  date.setDate(date.getDate() + d);

  // Skip weekends
  if (date.getDay() === 0 || date.getDay() === 6) continue;

  for (let h = START_HOUR; h < END_HOUR; h++) {
    for (let m = 0; m < 60; m += SLOT_DURATION) {
      const slotStart = new Date(date);
      slotStart.setHours(h, m, 0, 0);
      const slotEnd = new Date(slotStart);
      slotEnd.setMinutes(slotEnd.getMinutes() + SLOT_DURATION);

      // Vérifier si le créneau est libre
      const isOccupied = events.some(e => {
        const eStart = new Date(e.start?.dateTime || e.start?.date);
        const eEnd = new Date(e.end?.dateTime || e.end?.date);
        return slotStart < eEnd && slotEnd > eStart;
      });

      if (!isOccupied) {
        slots.push({
          start: slotStart.toISOString(),
          end: slotEnd.toISOString(),
          label: slotStart.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' }) + ' à ' + slotStart.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })
        });
      }
    }
  }
}

// Retourner les 6 premiers créneaux
return [{ json: { available_slots: slots.slice(0, 6) } }];

